{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table eggozdb.maplemonk.logistic_cost as select rr2.code as distributor_name, tt.* from ( select oo.name bill_name, oo.status, cast(timestampadd(minute, 660, oo.delivery_date) as date) delivery_date, max(cast(timestampadd(minute, 660, oo.delivery_date) as date)) over (partition by rr.code) last_order_date , sum(oo.order_price_amount) order_price_amount,sst.id as beat_assignment_id, cast(timestampadd(minute, 660, sst.beat_date ) as date) as beat_date, ol.quantity * (ol.single_sku_rate + ol.single_sku_discount+ol.single_sku_tax) sale, sum(oo.discount_amount+oo.scheme_discount_amount)/(count(oo.name) over (partition by cast(timestampadd(minute, 660, oo.delivery_date) as date), oo.retailer_id, oo.name)) discount, sp.id as salesperson_id , cu.name, cu.email, ol.single_sku_mrp, ol.single_sku_rate, ol.single_sku_discount,ol.single_sku_tax, ol.quantity*pp.sku_count AS eggs_sold, concat(pp.sku_count,pp.short_name) sku, pp.slug, ol.quantity, pp.product_type, pps.name as sku_category, oo.retailer_id, rr.code as retailer_name, rp.name as parent_retailer_name, rr.area_classification, rr.beat_number beat_number_original, sst.beat_number as beat_number_operations, bc.cluster_name, sst.beat_name, rr.onboarding_status, rr.city_id, rr.distributor_id, rcc.name as retailer_category, oo.warehouse_id, avg(wv.adhoc_cost) adhoc_cost,avg(wv.pre_cost) over (partition by sst.beat_date,sst.id) pre_cost, CASE WHEN SUM(wv.pre_cost) > 0 AND SUM(ol.quantity * pp.sku_count) > 0 THEN AVG(pre_cost+adhoc_cost) OVER (PARTITION BY wv.beat_assignment_id)/SUM(eggs_sold) OVER (PARTITION BY wv.beat_assignment_id) ELSE 0 END AS per_egg_cost from eggozdb.maplemonk.my_sql_order_order oo left join eggozdb.maplemonk.my_sql_distributionchain_beatassignment sst on sst.id = oo.beat_assignment_id left join eggozdb.maplemonk.my_sql_warehouse_vehicletripdetail wv on sst.id = wv.beat_assignment_id left join eggozdb.maplemonk.my_sql_retailer_retailer rr on rr.id = oo.retailer_id left join eggozdb.maplemonk.my_sql_retailer_retailerparent rp on rr.parent_id = rp.id left join eggozdb.maplemonk.my_sql_retailer_customer_category rcc on rcc.id = rr.category_id left join eggozdb.maplemonk.my_sql_order_orderline ol on ol.order_id = oo.id left join eggozdb.maplemonk.my_sql_product_product pp on pp.id = ol.product_id left join eggozdb.maplemonk.my_sql_PRODUCT_PRODUCTSUBDIVISION pps on pp.productSubDivision_id=pps.id left join eggozdb.maplemonk.my_sql_base_cluster bc on rr.cluster_id = bc.id left join eggozdb.maplemonk.my_sql_saleschain_salespersonprofile sp on oo.SALESPERSON_ID=sp.id left join eggozdb.maplemonk.my_sql_custom_auth_user cu on sp.user_id = cu.id where lower(oo.status) in (\'delivered\',\'completed\') group by cast(timestampadd(minute, 660, oo.delivery_date) as date), oo.retailer_id,oo.delivery_date, oo.name, pp.name, pp.short_name, pp.slug, oo.status, ol.quantity, wv.pre_cost, pp.sku_count, pp.product_type, wv.beat_assignment_id,sst.id, rr.area_classification, pp.slug, rr.code, rp.name, rr.beat_number, sst.beat_number, sst.beat_name, rr.onboarding_status, rr.city_id, rr.distributor_id, ol.single_sku_rate, ol.single_sku_mrp,wv.adhoc_cost,sst.beat_date,ol.single_sku_discount,ol.single_sku_tax,sp.id,cu.name,cu.email,pps.name, bc.cluster_name, rcc.name, oo.warehouse_id ) tt left join eggozdb.maplemonk.my_sql_retailer_retailer rr2 on rr2.id = tt.distributor_id ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            